\begin{knowledgebox}{最小可运行 Agent 循环}
\[
\text{Trajectory}_{t}
\xrightarrow{\text{LLM}}
\text{Thought + Tool Call}
\xrightarrow{\text{Environment}}
\text{Observation}_{t+1}
\xrightarrow{\text{append}}
\text{Trajectory}_{t+1}
\]
